#include <format>
#include <iostream>
#include <string_view>
#include <vector>

constexpr double hours_per_year = 8760.0;

// A chain: every part must work, so the availabilities multiply.
[[nodiscard]] constexpr double in_series(double availability, int parts) {
  double product = 1.0;
  for (int i = 0; i < parts; ++i) product *= availability;
  return product;
}

// Two copies where either one is enough, with `common` the share of the failures that take both
// down at once: the same bug, the same bad input, the same power supply.
[[nodiscard]] constexpr double in_parallel(double availability, double common) {
  const double down = 1.0 - availability;
  const double independent = (1.0 - common) * down;
  return 1.0 - (common * down + independent * independent);
}

struct Row {
  std::string_view what;
  double availability;
};

int main() {
  const std::vector<Row> rows{
      {.what = "one part, 0.99", .availability = 0.99},
      {.what = "one part, 0.999", .availability = 0.999},
      {.what = "one part, 0.9999", .availability = 0.9999},
      {.what = "six 0.999 parts in series", .availability = in_series(0.999, 6)},
      {.what = "ten 0.999 parts in series", .availability = in_series(0.999, 10)},
      {.what = "two 0.999 parts, failures independent", .availability = in_parallel(0.999, 0.0)},
      {.what = "two 0.999 parts, 1 in 100 failures common", .availability = in_parallel(0.999, 0.01)},
      {.what = "two 0.999 parts, 1 in 10 failures common", .availability = in_parallel(0.999, 0.10)},
  };

  std::cout << std::format("{:<42} {:>10} {:>14}\n", "arrangement", "available", "down per year");
  for (const Row& row : rows) {
    const double down_hours = (1.0 - row.availability) * hours_per_year;
    const std::string down = down_hours >= 1.0 ? std::format("{:.1f} h", down_hours)
                                               : std::format("{:.0f} min", down_hours * 60.0);
    std::cout << std::format("{:<42} {:>10.6f} {:>14}\n", row.what, row.availability, down);
  }
}

#include <algorithm>
#include <chrono>
#include <cstdint>
#include <format>
#include <iostream>
#include <optional>
#include <random>
#include <string>

using Millis = std::chrono::milliseconds;

// What the caller is willing to spend on one request before it gives up and reports the failure.
struct Budget {
  Millis base;            // the first window
  Millis cap;             // the window never grows past this
  std::int64_t attempts;  // including the first one
  Millis total;           // wall time for the whole sequence
};

// The window the doubling produced, and the wait drawn from it.
struct Step {
  Millis window;
  Millis wait;
};

// Full jitter: wait a uniform time in [0, window], where the window doubles after each failure.
// Plain doubling puts every client back on the wire at the same instants; the random draw spreads
// them. Time arrives as an argument and the generator is a member, so a test replays any timeline.
class Retry {
 public:
  Retry(Budget budget, std::uint32_t seed) : budget_(budget), generator_(seed) {}

  // The next wait, or nothing when the attempts or the time are spent.
  [[nodiscard]] std::optional<Step> after_failure(Millis elapsed) {
    ++failures_;
    if (failures_ >= budget_.attempts) return std::nullopt;
    const std::int64_t doublings = std::min<std::int64_t>(failures_ - 1, 20);
    const Millis window{std::min(budget_.cap.count(), budget_.base.count() << doublings)};
    const Millis wait{static_cast<std::int64_t>(generator_() % static_cast<std::uint32_t>(window.count() + 1))};
    if (elapsed + wait > budget_.total) return std::nullopt;
    return Step{.window = window, .wait = wait};
  }

 private:
  Budget budget_;
  std::mt19937 generator_;
  std::int64_t failures_ = 0;
};

int main() {
  const Budget budget{.base = Millis{100}, .cap = Millis{2000}, .attempts = 8, .total = Millis{5000}};
  Retry retry{budget, 20260921U};

  std::cout << std::format("{:>7} {:>9} {:>9} {:>9}\n", "failure", "window", "wait", "elapsed");
  Millis elapsed{0};
  for (std::int64_t failure = 1;; ++failure) {
    const std::optional<Step> step = retry.after_failure(elapsed);
    if (!step) {
      std::cout << std::format("{:>7} {:>9} {:>9} {:>9}\n", failure, "-", "give up", elapsed.count());
      break;
    }
    elapsed += step->wait;
    std::cout << std::format("{:>7} {:>9} {:>9} {:>9}\n", failure, step->window.count(), step->wait.count(),
                             elapsed.count());
  }

  // Five clients that failed together, shown on their third failure. Doubling alone would put all
  // five back on the wire 400 ms later; the draw spreads them across the window.
  std::string spread;
  for (const std::uint32_t seed : {7919U, 104729U, 1299709U, 15485863U, 179424673U}) {
    Retry client{budget, seed};
    std::optional<Step> step;
    for (int attempt = 0; attempt < 3; ++attempt) step = client.after_failure(Millis{0});
    if (!spread.empty()) spread += ", ";
    spread += std::format("{} ms", step ? step->wait.count() : 0);
  }
  std::cout << std::format("five clients after their third failure, window 400 ms: {}\n", spread);
}
